text:
Componente para Next.js App Router. Usa `IntersectionObserver`, por lo que no agrega un listener de scroll continuo.

```tsx
// components/site-navbar.tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const links = [
  { href: "#servicios", label: "Servicios" },
  { href: "#proyectos", label: "Proyectos" },
  { href: "#contacto", label: "Contacto" },
] as const;

type SiteNavbarProps = {
  heroId?: string;
};

export function SiteNavbar({ heroId = "hero" }: SiteNavbarProps) {
  const [hasPassedHero, setHasPassedHero] = useState(false);

  useEffect(() => {
    const hero = document.getElementById(heroId);

    if (!hero) {
      console.warn(`SiteNavbar: no se encontró el elemento #${heroId}.`);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        setHasPassedHero(entry.boundingClientRect.bottom <= 0);
      },
      { threshold: 0 },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, [heroId]);

  return (
    <header
      className={[
        "fixed inset-x-0 top-0 z-50 transition-[background-color,box-shadow,border-color] duration-500 ease-out",
        hasPassedHero
          ? "border-b border-black/6 bg-[#f7f4ed]/92 shadow-[0_12px_40px_-18px_rgba(20,18,14,0.3)] backdrop-blur-xl"
          : "border-b border-transparent bg-transparent shadow-none",
      ].join(" ")}
    >
      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-20 max-w-7xl items-center justify-between px-6 lg:px-10"
      >
        <Link
          href="/"
          className={[
            "text-lg font-semibold tracking-[-0.04em] transition-colors duration-500",
            hasPassedHero ? "text-[#191712]" : "text-white",
          ].join(" ")}
        >
          Estudio Norte
        </Link>

        <div className="flex items-center gap-2 sm:gap-6">
          <ul className="hidden items-center gap-7 md:flex">
            {links.map((link) => (
              <li key={link.href}>
                <Link
                  href={link.href}
                  className={[
                    "text-sm transition-colors duration-300",
                    hasPassedHero
                      ? "text-[#5d584e] hover:text-[#191712]"
                      : "text-white/75 hover:text-white",
                  ].join(" ")}
                >
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>

          <Link
            href="#contacto"
            className={[
              "rounded-full px-5 py-2.5 text-sm font-medium transition-colors duration-300",
              hasPassedHero
                ? "bg-[#191712] text-white hover:bg-[#363126]"
                : "bg-white text-[#191712] hover:bg-white/85",
            ].join(" ")}
          >
            Hablemos
          </Link>
        </div>
      </nav>
    </header>
  );
}
```

El hero debe llevar el mismo `id`:

```tsx
<>
  <SiteNavbar />

  <main>
    <section id="hero" className="min-h-screen">
      {/* Hero */}
    </section>

    {/* Resto de la página */}
  </main>
</>
```

El cambio ocurre cuando el borde inferior del hero abandona completamente la parte superior del viewport.
